60,1267115,37273673,36864800,35502972,44383741,45640652,1980142,36469617,37275666,36872238,36987485,35513803,44383160,1581884,45639609,1982788,1720062,36088025,44779836,36470882,44387509,43049609,36976520,1261932,36373634,1109501,45651977,44406353,42881400,1258078,36375985,43049822,44407450,42881835,1264381,36371612,791761,44394765,42882954,35203458,36379414,799838,44391197,1800150,36336182,45785426,1209997,1240606,35303717,36343394,1237844,45785681,36165663,45783934,36343543,1232538,1232449,598027,1231731,1625071,592454,45790458,592866,45787115,42886241,35600579,35601035,36168997,45894997,36371993,35509703,42883473,44382583,36474199,44379774,42815816,44377652,45639102,1767386,45666964,44369796,37618151,42516412,2517572,44779682,35530375,44367789,45641836,42881200,1109409,44386935,42817381,37410630,36872240,36300381,36398969,36345958,36986214,42815576,42882827,45645672,44383868,1509398,42816024,37273674,36865183,36468735,36336102,36088212,37001233,42645861,45790438,1267011,45646215,44384863,1482374,36600325,42694459,1439734,621636,36325923,36087789,1218295,42794777,42886906,45793646,45651548,44382103,35903405,634795,821257,971709,36322862,1088054,728576,1980036,1231596,45650263,44369418,35899513,3993219,44779228,35837170,36100935,44379376,35513515,45663902,35836371,44375345,1800154,44388451,35203536,45699273,37138941,44393089,1264555,44401480,1262004,36163526,817972,37135705,818455,1357402,37138096,45627258,45708006,35903913,45802084,45779529,44377416,46244088,44380206,736912,36470612,35509368,45626505,45685842,45670751,45634862,45629645,1080475,37127028,37275878,42648558,1276404,36141560,1474362,36415884,3997532,37127127,36976591,42795099,707129,37122105,596170,1999446,707357,1248099,35800309,36400543,1964177,1248364,1994556,1262390,1983441,1542579,971994,35998019,1526950,43547428,42886123,3944521,1542615,36869546,835267,42648080,621403,37552194,36375784,36400665,1827024,36875533,1965079,1262341,629053,1476807,1475187,1323487,1834642,37576689,37401078,1248313,3987998,37143895,1053051,1248320,707347,1046851,1778816,1081120,37552099,1964156,35301481,1827256,35121586,1475249,1248386,1744136,37143923,35998277,1262397,3993546,36871257,598137,1109611,3993916,36864466,1382242,707367,36325141,45672396,45680659,42807334,44348121,45673251,44350233,44346367,44351272,45671635,44351821,42804635,44356512,45672368,44364079,44341882,45665986,44343841,45693550,45623838,45623953,45626555,45657331,45662547,35529627,621575,35530251,1392325,736239,45701079,45666503,728706,45630544,44352182,1460630,45705320,46295415,35507670,46299415,36463263,1122113,45632294,45708304))

) I
) C UNION ALL 
SELECT 5 as codeset_id, c.concept_id FROM (select distinct I.concept_id FROM
( 
  select concept_id from deid_omop.CONCEPT where (concept_id in (4324383,4013964,3016723,3045262,37028633,4324383,2212294,3053283,3049187,3045262,37028633,44790183,40771922,1619025,3029859,36306178,3053283,36303797,3049187,36662614))
UNION  select c.concept_id
  from deid_omop.CONCEPT c
  join deid_omop.CONCEPT_ANCESTOR ca on c.concept_id = ca.descendant_concept_id
  WHERE c.invalid_reason is null
  and (ca.ancestor_concept_id in (4324383,4013964,3016723,3045262,37028633,4324383,2212294,3053283,3049187,3045262,37028633,44790183,40771922,1619025,3029859,36306178,3053283,36303797,3049187,36662614))

) I
) C
),

-- ATLAS primary event: first codeset-0 condition era per person, within an
-- observation period and with at least 365 days of prior observation.
primary_event_candidates AS (
    SELECT
        ce.person_id,
        ce.condition_era_id AS source_event_id,
        ce.condition_era_start_date AS start_date,
        ce.condition_era_end_date AS end_date,
        op.observation_period_start_date AS op_start_date,
        op.observation_period_end_date AS op_end_date,
        ROW_NUMBER() OVER (
            PARTITION BY ce.person_id
            ORDER BY ce.condition_era_start_date, ce.condition_era_id
        ) AS event_ordinal
    FROM deid_omop.condition_era ce
    JOIN codesets cs
      ON cs.codeset_id = 0
     AND cs.concept_id = ce.condition_concept_id
    JOIN deid_omop.observation_period op
      ON op.person_id = ce.person_id
     AND ce.condition_era_start_date BETWEEN
         op.observation_period_start_date AND op.observation_period_end_date
    WHERE date_add('day', 365, op.observation_period_start_date)
              <= ce.condition_era_start_date
),
qualified_events AS (
    SELECT
        CAST(1 AS bigint) AS event_id,
        person_id,
        start_date,
        end_date,
        op_start_date,
        op_end_date
    FROM primary_event_candidates
    WHERE event_ordinal = 1
),

-- Inclusion rule 0: age 
inclusion_0 AS (
    SELECT q.person_id, q.event_id
    FROM qualified_events q
    JOIN deid_omop.person p ON p.person_id = q.person_id
    WHERE year(q.start_date) - p.year_of_birth > 18
),

-- Inclusion rule 1: at least one condition era
inclusion_1 AS (
    SELECT DISTINCT q.person_id, q.event_id
    FROM qualified_events q
    JOIN deid_omop.condition_era ce
      ON ce.person_id = q.person_id
     AND ce.condition_era_start_date BETWEEN q.op_start_date AND q.op_end_date
    JOIN codesets cs
      ON cs.concept_id = ce.condition_concept_id
     AND cs.codeset_id IN (1, 2, 3)
),

-- Inclusion rule 2: at least one codeset-4 drug exposure starting on or after index
inclusion_2 AS (
    SELECT DISTINCT q.person_id, q.event_id
    FROM qualified_events q
    JOIN deid_omop.drug_exposure de
      ON de.person_id = q.person_id
     AND de.drug_exposure_start_date BETWEEN q.start_date AND q.op_end_date
    JOIN codesets cs
      ON cs.codeset_id = 4
     AND cs.concept_id = de.drug_concept_id
),

-- Inclusion rule 3: baselin + treatment
baseline_measurement AS (
    SELECT DISTINCT q.person_id, q.event_id
    FROM qualified_events q
    JOIN deid_omop.measurement m
      ON m.person_id = q.person_id
     AND m.measurement_date BETWEEN date_add('day', -365, q.start_date)
                                AND q.start_date
     AND m.measurement_date BETWEEN q.op_start_date AND q.op_end_date
    JOIN codesets cs
      ON cs.codeset_id = 5
     AND cs.concept_id = m.measurement_concept_id
),
followup_measurement AS (
    SELECT DISTINCT q.person_id, q.event_id
    FROM qualified_events q
    JOIN deid_omop.measurement m
      ON m.person_id = q.person_id
     AND m.measurement_date BETWEEN date_add('day', 90, q.start_date)
                                AND date_add('day', 365, q.start_date)
     AND m.measurement_date BETWEEN q.op_start_date AND q.op_end_date
    JOIN codesets cs
      ON cs.codeset_id = 5
     AND cs.concept_id = m.measurement_concept_id
),
inclusion_3 AS (
    SELECT b.person_id, b.event_id
    FROM baseline_measurement b
    JOIN followup_measurement f
      ON f.person_id = b.person_id
     AND f.event_id = b.event_id
),

included_events AS (
    SELECT q.*
    FROM qualified_events q
    JOIN inclusion_0 i0 ON i0.person_id = q.person_id AND i0.event_id = q.event_id
    JOIN inclusion_1 i1 ON i1.person_id = q.person_id AND i1.event_id = q.event_id
    JOIN inclusion_2 i2 ON i2.person_id = q.person_id AND i2.event_id = q.event_id
    JOIN inclusion_3 i3 ON i3.person_id = q.person_id AND i3.event_id = q.event_id
),

drug_target AS (
    SELECT
        de.person_id,
        de.drug_exposure_start_date AS start_date,
        COALESCE(
            de.drug_exposure_end_date,
            date_add('day', CAST(de.days_supply AS bigint), de.drug_exposure_start_date),
            date_add('day', 1, de.drug_exposure_start_date)
        ) AS exposure_end_date
    FROM deid_omop.drug_exposure de
    JOIN (SELECT DISTINCT person_id FROM included_events) p
      ON p.person_id = de.person_id
    JOIN codesets cs
      ON cs.codeset_id = 4
     AND cs.concept_id = de.drug_concept_id

    UNION ALL

    SELECT
        de.person_id,
        de.drug_exposure_start_date AS start_date,
        COALESCE(
            de.drug_exposure_end_date,
            date_add('day', CAST(de.days_supply AS bigint), de.drug_exposure_start_date),
            date_add('day', 1, de.drug_exposure_start_date)
        ) AS exposure_end_date
    FROM deid_omop.drug_exposure de
    JOIN (SELECT DISTINCT person_id FROM included_events) p
      ON p.person_id = de.person_id
    JOIN codesets cs
      ON cs.codeset_id = 4
     AND cs.concept_id = de.drug_source_concept_id
),
extended_drug_intervals AS (
    SELECT
        person_id,
        start_date,
        date_add('day', 365, exposure_end_date) AS end_date
    FROM drug_target
),
drug_interval_starts AS (
    SELECT
        person_id,
        start_date,
        end_date,
        CASE
            WHEN MAX(end_date) OVER (
                PARTITION BY person_id
                ORDER BY start_date
                ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
            ) >= start_date THEN 0
            ELSE 1
        END AS is_start
    FROM extended_drug_intervals
),
drug_interval_groups AS (
    SELECT
        person_id,
        start_date,
        end_date,
        SUM(is_start) OVER (
            PARTITION BY person_id
            ORDER BY start_date, is_start DESC
            ROWS UNBOUNDED PRECEDING
        ) AS group_idx
    FROM drug_interval_starts
),
drug_eras AS (
    SELECT
        person_id,
        MIN(start_date) AS era_start_date,
        MAX(end_date) AS era_end_date
    FROM drug_interval_groups
    GROUP BY person_id, group_idx
),
strategy_ends AS (
    SELECT i.event_id, i.person_id, e.era_end_date AS end_date
    FROM included_events i
    JOIN drug_eras e
      ON e.person_id = i.person_id
     AND i.start_date BETWEEN e.era_start_date AND e.era_end_date
),
death_ends AS (
    SELECT i.event_id, i.person_id, MIN(d.death_date) AS end_date
    FROM included_events i
    JOIN deid_omop.death d
      ON d.person_id = i.person_id
     AND d.death_date BETWEEN i.start_date AND i.op_end_date
    GROUP BY i.event_id, i.person_id
),
all_end_candidates AS (
    SELECT event_id, person_id, op_end_date AS end_date FROM included_events
    UNION ALL
    SELECT event_id, person_id, end_date FROM strategy_ends
    UNION ALL
    SELECT event_id, person_id, end_date FROM death_ends
),
cohort_rows AS (
    SELECT
        i.person_id,
        i.start_date,
        MIN(e.end_date) AS end_date
    FROM included_events i
    JOIN all_end_candidates e
      ON e.event_id = i.event_id
     AND e.person_id = i.person_id
     AND e.end_date >= i.start_date
    GROUP BY i.person_id, i.start_date
),

cohort_row_starts AS (
    SELECT
        person_id,
        start_date,
        end_date,
        CASE
            WHEN MAX(end_date) OVER (
                PARTITION BY person_id
                ORDER BY start_date
                ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
            ) >= start_date THEN 0
            ELSE 1
        END AS is_start
    FROM cohort_rows
),
cohort_row_groups AS (
    SELECT
        person_id,
        start_date,
        end_date,
        SUM(is_start) OVER (
            PARTITION BY person_id
            ORDER BY start_date, is_start DESC
            ROWS UNBOUNDED PRECEDING
        ) AS group_idx
    FROM cohort_row_starts
),
final_cohort AS (
    SELECT
        person_id,
        MIN(start_date) AS start_date,
        MAX(end_date) AS end_date
    FROM cohort_row_groups
    GROUP BY person_id, group_idx
)
SELECT
    person_id,
    start_date,
    end_date
FROM final_cohort;

-- run separately
SELECT COUNT(*) AS cohort_rows,
        COUNT(DISTINCT person_id) AS unique_patients
 FROM llin11.lisinopril_final_cohort;


-- measurement count (table 2)
WITH measurement_inventory AS (

    -- Baseline measurements
    SELECT
        'Baseline' AS measurement_window,
        m.measurement_concept_id,
        m.unit_concept_id,
        COUNT(*) AS measurement_count,
        COUNT(DISTINCT m.person_id) AS patient_count
    FROM llin11.lisinopril_final_cohort c
    JOIN deid_omop.measurement m
        ON m.person_id = c.person_id
       AND m.measurement_date BETWEEN
           date_add('day', -365, c.start_date)
           AND c.start_date
    WHERE m.value_as_number IS NOT NULL
    GROUP BY
        m.measurement_concept_id,
        m.unit_concept_id

    UNION ALL

    -- Follow-up measurements
    SELECT
        'Follow-up' AS measurement_window,
        m.measurement_concept_id,
        m.unit_concept_id,
        COUNT(*) AS measurement_count,
        COUNT(DISTINCT m.person_id) AS patient_count
    FROM llin11.lisinopril_final_cohort c
    JOIN deid_omop.measurement m
        ON m.person_id = c.person_id
       AND m.measurement_date BETWEEN
           date_add('day', 90, c.start_date)
           AND date_add('day', 365, c.start_date)
    WHERE m.value_as_number IS NOT NULL
    GROUP BY
        m.measurement_concept_id,
        m.unit_concept_id
)

SELECT
    i.measurement_window,
    i.measurement_concept_id,
    mc.concept_name AS measurement_name,
    i.unit_concept_id,
    uc.concept_name AS unit_name,
    i.measurement_count,
    i.patient_count
FROM measurement_inventory i
LEFT JOIN deid_omop.concept mc
    ON mc.concept_id = i.measurement_concept_id
LEFT JOIN deid_omop.concept uc
    ON uc.concept_id = i.unit_concept_id
WHERE lower(mc.concept_name) LIKE '%glomerular filtration%'
   OR lower(mc.concept_name) LIKE '%egfr%'
   OR lower(mc.concept_name) LIKE '%creatinine%'
ORDER BY
    measurement_name,
    unit_name,
    measurement_window;

-- measurement analysis (baseline vs treatment)

-- DROP TABLE IF EXISTS llin11.lisinopril_creatinine_paired;

CREATE TABLE llin11.lisinopril_creatinine_paired AS

WITH baseline_ranked AS (
    SELECT
        c.person_id,
        c.start_date AS index_date,
        m.measurement_id,
        m.measurement_date,
        m.value_as_number,
        ROW_NUMBER() OVER (
            PARTITION BY c.person_id
            ORDER BY
                m.measurement_date DESC,
                m.measurement_id DESC
        ) AS measurement_rank
    FROM llin11.lisinopril_final_cohort c
    JOIN deid_omop.measurement m
        ON m.person_id = c.person_id
       AND m.measurement_date BETWEEN
           date_add('day', -365, c.start_date)
           AND c.start_date
    WHERE m.measurement_concept_id = 3016723
      AND m.unit_concept_id = 8840
      AND m.value_as_number IS NOT NULL
),

followup_ranked AS (
    SELECT
        c.person_id,
        c.start_date AS index_date,
        m.measurement_id,
        m.measurement_date,
        m.value_as_number,
        ROW_NUMBER() OVER (
            PARTITION BY c.person_id
            ORDER BY
                m.measurement_date DESC,
                m.measurement_id DESC
        ) AS measurement_rank
    FROM llin11.lisinopril_final_cohort c
    JOIN deid_omop.measurement m
        ON m.person_id = c.person_id
       AND m.measurement_date BETWEEN
           date_add('day', 90, c.start_date)
           AND date_add('day', 365, c.start_date)
    WHERE m.measurement_concept_id = 3016723
      AND m.unit_concept_id = 8840
      AND m.value_as_number IS NOT NULL
),

baseline AS (
    SELECT *
    FROM baseline_ranked
    WHERE measurement_rank = 1
),

followup AS (
    SELECT *
    FROM followup_ranked
    WHERE measurement_rank = 1
)

SELECT
    b.person_id,
    b.index_date,

    b.measurement_id AS baseline_measurement_id,
    b.measurement_date AS baseline_date,
    date_diff('day', b.measurement_date, b.index_date)
        AS baseline_days_before_index,
    b.value_as_number AS baseline_creatinine_mg_dl,

    f.measurement_id AS followup_measurement_id,
    f.measurement_date AS followup_date,
    date_diff('day', f.index_date, f.measurement_date)
        AS followup_days_after_index,
    f.value_as_number AS followup_creatinine_mg_dl,

    f.value_as_number - b.value_as_number
        AS creatinine_change_mg_dl,

    CASE
        WHEN b.value_as_number <> 0
        THEN 100.0 * (
            f.value_as_number - b.value_as_number
        ) / b.value_as_number
    END AS creatinine_percent_change

FROM baseline b
JOIN followup f
    ON f.person_id = b.person_id;

SELECT
    (SELECT COUNT(*)
     FROM llin11.lisinopril_final_cohort) AS original_cohort_size,

    COUNT(*) AS paired_sample_size,

    (SELECT COUNT(*)
     FROM llin11.lisinopril_final_cohort) - COUNT(*)
        AS patients_without_complete_pair,

    ROUND(
        100.0 * COUNT(*) /
        (SELECT COUNT(*) FROM llin11.lisinopril_final_cohort),
        1
    ) AS percent_with_complete_pair

FROM llin11.lisinopril_creatinine_paired;

SELECT
    COUNT(*) AS paired_patients,

    AVG(baseline_creatinine_mg_dl) AS baseline_mean,
    STDDEV_SAMP(baseline_creatinine_mg_dl) AS baseline_sd,
    approx_percentile(baseline_creatinine_mg_dl, 0.5)
        AS baseline_median,

    AVG(followup_creatinine_mg_dl) AS followup_mean,
    STDDEV_SAMP(followup_creatinine_mg_dl) AS followup_sd,
    approx_percentile(followup_creatinine_mg_dl, 0.5)
        AS followup_median,

    AVG(creatinine_change_mg_dl) AS mean_change,
    STDDEV_SAMP(creatinine_change_mg_dl) AS change_sd,
    approx_percentile(creatinine_change_mg_dl, 0.5)
        AS median_change,

    approx_percentile(
        creatinine_change_mg_dl,
        ARRAY[0.25, 0.75]
    ) AS change_quartiles,

    MIN(creatinine_change_mg_dl) AS minimum_change,
    MAX(creatinine_change_mg_dl) AS maximum_change

FROM llin11.lisinopril_creatinine_paired;

SELECT
    baseline_creatinine_mg_dl,
    followup_creatinine_mg_dl,
    creatinine_change_mg_dl,
    creatinine_percent_change
FROM llin11.lisinopril_creatinine_paired
ORDER BY person_id;
